// =====================================================================================
//  CONFIG - everything you need to change lives here.
//  Secrets do NOT live here; they are n8n credentials (Telegram, Supabase, Apify,
//  RapidAPI, Bland). This node holds the non-secret settings only.
// =====================================================================================
return [{ json: { config: {

  // --- the mountain -----------------------------------------------------------------
  resortUrl:      'https://www.snow-forecast.com/resorts/Niseko/6day/top',
  resortName:     'Niseko Grand Hirafu',
  liftLat:        42.8615,       // Hirafu gondola, used for the boot-walk ranking
  liftLng:        140.6982,

  // --- the trigger ------------------------------------------------------------------
  snowCm:         40,            // overnight dump that counts
  coldC:          -10,           // must stay at or below this...
  coldRunDays:    3,             // ...for this many days straight
  tripNights:     5,

  // --- travel -----------------------------------------------------------------------
  homeAirport:    'PER',
  arriveAirport:  'CTS',         // Sapporo New Chitose
  adults:         4,

  // --- the arrival sequence ---------------------------------------------------------
  transferLeadMins: 30,          // book the taxi this long before touchdown
  beerLeadMins:     10,          // order the beers this many minutes from the chalet

  // Saved contacts. Swap these for the operators you actually use.
  taxiContact:  { name: 'Niseko Taxi',        phone: 'YOUR_PHONE_NUMBER' },
  beerContact:  { name: 'Hirafu Bottle Shop', phone: 'YOUR_PHONE_NUMBER' },

  // --- who gets told ----------------------------------------------------------------
  telegramChatId: 'YOUR_TELEGRAM_CHAT_ID',
} }}];

// Parse snow-forecast.com's server-rendered table. There is no API; the rows are
// semantically tagged with data-row=..., and 18 columns = 6 days x (AM, PM, night).
const doc = $input.first().json.data || '';
if (!doc || doc.length < 5000) {
  throw new Error('snow-forecast returned ' + doc.length + ' chars - blocked or layout changed');
}
function row(name) {
  const m = doc.match(new RegExp('<tr class="forecast-table__row" data-row="' + name + '"[\\s\\S]*?<\\/tr>'));
  if (!m) return [];
  return [...m[0].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)].map(function (c) {
    return c[1].replace(/<[^>]+>/g, ' ').replace(/&[a-z]+;/g, ' ').replace(/\s+/g, ' ').trim();
  });
}
const num = function (v) {
  const n = parseFloat(String(v).replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
};

const days = row('days');
const time = row('time');
const snow = row('snow').map(num);
const tmax = row('temperature-max').map(num);
const tmin = row('temperature-min').map(num);
const wind = row('wind');
const phrase = row('phrases');
const freeze = row('freezing-level').map(num);

if (time.length === 0) {
  throw new Error('table found but 0 periods parsed - snow-forecast changed its markup');
}

const periods = time.map(function (t, i) {
  return {
    period: t,
    snow_cm: snow[i] || 0,
    tmax: tmax[i] || 0,
    tmin: tmin[i] || 0,
    wind: wind[i] || '',
    sky: phrase[i] || '',
    freezing_level_m: freeze[i] || 0,
  };
});

const base = new Date();
const iso = function (offsetDays) {
  return new Date(base.getTime() + offsetDays * 86400000).toISOString().slice(0, 10);
};

const daily = days.map(function (d, di) {
  const p = periods.slice(di * 3, di * 3 + 3);
  const night = p.filter(function (x) { return x.period === 'night'; })[0];
  return {
    day: d,
    date: iso(di),
    snow_cm_total: +p.reduce(function (s, x) { return s + x.snow_cm; }, 0).toFixed(1),
    snow_cm_overnight: night ? night.snow_cm : 0,
    tmax: Math.max.apply(null, p.map(function (x) { return x.tmax; })),
    tmin: Math.min.apply(null, p.map(function (x) { return x.tmin; })),
    sky: p.map(function (x) { return x.sky; }).join(' / '),
    periods: p,
  };
});

return [{ json: {
  resort: 'Niseko Grand Hirafu (top station)',
  source: 'snow-forecast.com',
  scraped_at: new Date().toISOString(),
  days_parsed: daily.length,
  daily: daily,
} }];

// The three conditions, straight off the script:
//   40cm overnight + under -10C for three days straight + clear skies on the fourth.
const d = $input.first().json;
const daily = d.daily || [];
const SNOW_CM = 40;
const COLD_C = -10;
const COLD_RUN = 3;

let dump = null;
for (const day of daily) {
  if (day.snow_cm_overnight >= SNOW_CM || day.snow_cm_total >= SNOW_CM) { dump = day; break; }
}

let run = 0, start = -1;
for (let i = 0; i < daily.length; i++) {
  if (daily[i].tmax <= COLD_C) {
    if (run === 0) start = i;
    run++;
    if (run >= COLD_RUN) break;
  } else { run = 0; start = -1; }
}
const coldOK = run >= COLD_RUN;
const fourth = coldOK ? daily[start + COLD_RUN] : null;
const clearOK = !!fourth && /clear|sunny|fair|some sun/i.test(fourth.sky);

const conditions = {
  dump: {
    ok: !!dump, need: SNOW_CM + 'cm',
    got: dump ? (dump.snow_cm_total + 'cm on ' + dump.day)
              : ('nothing over ' + SNOW_CM + 'cm in the next 6 days'),
  },
  cold: {
    ok: coldOK, need: COLD_RUN + ' days under ' + COLD_C + 'C',
    got: coldOK ? ('run starts ' + daily[start].day) : ('longest run is ' + run + ' day(s)'),
  },
  clear: {
    ok: clearOK, need: 'clear skies on the 4th day',
    got: fourth ? fourth.sky : 'no 4th day to check yet',
  },
};

const japow = conditions.dump.ok && conditions.cold.ok && conditions.clear.ok;
const snowiest = daily.slice().sort(function (a, b) {
  return b.snow_cm_total - a.snow_cm_total;
})[0];

// Trip window: fly in on the dump, stay 5 nights. The Apify legs need real dates.
const TRIP_NIGHTS = 5;
const anchor = dump || snowiest || daily[0];
const departDate = anchor ? anchor.date : null;
const returnDate = departDate
  ? new Date(new Date(departDate).getTime() + TRIP_NIGHTS * 86400000).toISOString().slice(0, 10)
  : null;

return [{ json: Object.assign({}, d, {
  japow: japow,
  conditions: conditions,
  headline: japow ? 'JAPOW WINDOW OPEN' : 'no window yet',
  best_day: dump ? dump.day : (snowiest ? snowiest.day : null),
  departDate: departDate,
  returnDate: returnDate,
  trip_nights: TRIP_NIGHTS,
}) }];

// Rank every chalet on how far you have to walk in snowboard boots, and let an onsen
// win outright. The 400m hard cut from the original script was removed 2026-08-31 --
// see the note further down.
const LIFT = { lat: 42.8615, lng: 140.6982 };   // Hirafu gondola base

function flat(items) {
  let a = items.map(function (i) { return i.json; });
  if (a.length === 1 && Array.isArray(a[0])) a = a[0];
  if (a.length === 1 && a[0] && Array.isArray(a[0].data)) a = a[0].data;
  return a;
}
function metres(lat, lng) {
  if (typeof lat !== 'number' || typeof lng !== 'number') return null;
  const R = 6371000;
  const toRad = function (x) { return x * Math.PI / 180; };
  const dLat = toRad(lat - LIFT.lat);
  const dLng = toRad(lng - LIFT.lng);
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.cos(toRad(LIFT.lat)) * Math.cos(toRad(lat)) *
            Math.sin(dLng / 2) * Math.sin(dLng / 2);
  return Math.round(R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
}
function nightly(it) {
  // Airbnb writes this as either "A$420 x 5 nights" or "5 nights x A$420", so anchor on
  // the CURRENCY symbol, not on the "x". The inherited SWELL EVENT regex took the number
  // after the "x" and therefore returned the NIGHT COUNT (5) as the nightly price.
  const desc = (((it.price || {}).breakDown || {}).basePrice || {}).description || '';
  const money = [...desc.matchAll(/[$£€¥]\s*([\d,]+(?:\.\d+)?)/g)]
    .map(function (m) { return parseFloat(m[1].replace(/,/g, '')); })
    .filter(function (n) { return !isNaN(n); });
  if (money.length) return Math.round(Math.max.apply(null, money));
  // Fallback: price.price is the TRIP TOTAL (qualifier "total"), not a nightly rate.
  // Divide it down rather than reporting a 5-night total as a per-night price.
  const price = (it.price || {});
  const alt = price.price || (it.pricing || {}).rate || null;
  const n = parseFloat(String(alt).replace(/[^0-9.]/g, ''));
  if (isNaN(n)) return null;
  const nightsMatch = String(desc).match(/(\d+)\s*nights?/i);
  const nights = nightsMatch ? parseInt(nightsMatch[1], 10) : 1;
  return Math.round(price.qualifier === 'total' && nights > 1 ? n / nights : n);
}

// --- flights ---
let f = $('Apify: flights PER to CTS').first().json;
if (Array.isArray(f)) f = f[0];
const flights = (f && (f.all_flights || f.best_flights)) || [];
const cheapest = flights.filter(function (x) { return x.price; })
                        .sort(function (a, b) { return a.price - b.price; })[0] || {};
const flightLine = cheapest.price
  ? ('A$' + cheapest.price + ' return (' + (cheapest.airlines || '?') +
     ((cheapest.stops === 0 || cheapest.stops === '0') ? ', direct' : '') + ')')
  : 'no fare returned';

// --- chalets ---
const raw = flat($('Apify: Niseko chalets').all());
const scored = raw.map(function (v) {
  // VERIFIED against a live tri_angle~airbnb-scraper run (2026-08-31):
  // coords live in `coordinates.latitude/.longitude`. `location` is a STRING
  // ("Kutchan"), NOT an object -- reading location.lat gave undefined, which made
  // walk_m null for every listing, which silently broke the boot-walk ranking.
  const c = v.coordinates || {};
  const loc = (v.location && typeof v.location === 'object') ? v.location : {};
  const lat = c.latitude != null ? c.latitude : (loc.lat != null ? loc.lat : v.lat);
  const lng = c.longitude != null ? c.longitude : (loc.lng != null ? loc.lng : v.lng);
  const blurb = [v.title, v.name, v.description, v.metaDescription,
                 v.locationSubtitle, (v.amenities || []).join(' ')]
                .filter(Boolean).join(' ').toLowerCase();
  return {
    name: v.title || v.name || 'chalet',
    url: (v.url || '').split('?')[0],
    nightly: nightly(v),
    walk_m: metres(lat, lng),
    lat: (typeof lat === 'number') ? lat : null,   // needed later: the arrival sequence
    lng: (typeof lng === 'number') ? lng : null,   // routes the taxi to these coords
    onsen: /onsen|hot spring|rotenburo|hot-spring/.test(blurb),
  };
});
// The 400m hard bin was REMOVED at Aaron's call (2026-08-31): against real Niseko
// inventory it binned all 6 listings (closest was 969m), so it only ever fired a fallback.
//
// With no cut, DISTANCE has to be the primary sort. Ranking onsen-first instead put an
// 8,877m chalet top of the list, which makes "ranked on how far you walk in snowboard
// boots" meaningless. So: shortest boot-walk wins, and an onsen only breaks a tie.
const keep = scored.slice().sort(function (a, b) {
  const da = a.walk_m == null ? 9999999 : a.walk_m;
  const db = b.walk_m == null ? 9999999 : b.walk_m;
  if (da !== db) return da - db;                      // shortest boot-walk wins...
  if (a.onsen !== b.onsen) return a.onsen ? -1 : 1;   // ...onsen breaks the tie
  return 0;
});

return [{ json: {
  flightLine: flightLine,
  flightPrice: cheapest.price || null,
  flightNumber: cheapest.flight_numbers || cheapest.flightNumber || null,
  chalet: keep[0] || {},
  chalets_considered: scored.length,
  walk_rule: 'ranked by boot-walk; onsen first. No distance cut.',
} }];

// Build the row we hand to Supabase. This is what makes the system stateful: the trip
// outlives this execution, so a workflow running days later can pick it up.
const s  = $('Evaluate JAPOW').first().json;
const p  = $('Rank by boot-walk').first().json;
const ch = p.chalet || {};
const c  = s.conditions || {};

return [{ json: {
  status:         'proposed',
  depart_date:    s.departDate,
  return_date:    s.returnDate,
  flight_number:  p.flightNumber || null,
  flight_date:    s.departDate,
  flight_line:    p.flightLine,
  flight_price:   p.flightPrice,
  chalet_name:    ch.name || null,
  chalet_url:     ch.url || null,
  chalet_lat:     ch.lat != null ? ch.lat : null,
  chalet_lng:     ch.lng != null ? ch.lng : null,
  chalet_nightly: ch.nightly != null ? ch.nightly : null,
  snow_summary:   [c.dump && c.dump.got, c.cold && c.cold.got, c.clear && c.clear.got]
                    .filter(Boolean).join(' | '),
} }];

const s = $('Evaluate JAPOW').first().json;
const p = $('Rank by boot-walk').first().json;
const c = s.conditions;
const ch = p.chalet || {};
const walk = ch.walk_m != null ? (ch.walk_m + 'm walk') : 'walk unknown';
const onsen = ch.onsen ? ' + ONSEN' : '';

// Short, dry, and readable on a phone. Every line earns its place.
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const short = function (iso) {
  if (!iso) return '?';
  const d = new Date(iso);
  return d.getUTCDate() + ' ' + MONTHS[d.getUTCMonth()];
};
const dates = short(s.departDate) + ' - ' + short(s.returnDate);

// Pull the bare numbers back out of the condition strings so the message stays tight.
const snowCm = (String(c.dump.got).match(/([\d.]+)cm/) || [])[1];
const coldDay = (function () {
  const days = (s.daily || []).filter(function (x) { return x.tmax <= -10; });
  return days.length ? Math.min.apply(null, days.map(function (x) { return x.tmax; })) : null;
})();

const lines = [
  '\u{1F3D4}️ <b>JAPOW EVENT</b>',
  'Niseko is about to get buried.',
  '',
  '❄️ <b>' + (snowCm ? snowCm + 'cm' : c.dump.got) + '</b> overnight',
  '\u{1F976} <b>' + (coldDay != null ? coldDay + '°C' : 'cold') + '</b> for three days straight',
  '☀️ Then it clears. Of course it does.',
  '',
  '\u{1F4C5} <b>' + dates + '</b> · ' + s.trip_nights + ' nights',
  '✈️ Perth → Sapporo · <b>' + p.flightLine + '</b>',
  '\u{1F3E0} ' + (ch.name || '?') + onsen,
  '   <b>A$' + (ch.nightly != null ? ch.nightly : '?') + '/night</b> · ' + walk,
  '   ' + (ch.url || ''),
  '',
  '\u{1F97E} Closest of ' + p.chalets_considered + ' to the lifts' +
    (ch.onsen ? ', and it has an onsen.' : '.'),
  '',
  '⏳ <b>Four hours.</b> Then it books without you.',
];
return [{ json: { text: lines.join('\n') } }];
